      "most_likely_effort": 2.5
    },
    {
      "activity_id": "A16",
      "activity_name": "U8: Example updates",
      "activity_description": "Update examples to show both the new individual MSP field functions and the existing GetMSP/SetMSP flow.",
      "most_likely_effort": 0.5
    },
    {
